-- Import of PF 2021 official exam items for the NEW career "Delegado de
-- Polícia Federal" (Edital nº 1 - DGP/PF, de 15 de janeiro de 2021,
-- CONCURSO PÚBLICO APLICAÇÃO: 2021, banca CEBRASPE). This exam is a
-- different career booklet from the "Agente de Polícia Federal" 2021 exam
-- already imported by 20260926050000 (and repaired by 20260927080000).
--
-- Source material read verbatim from Google Drive:
--   - Prova: CARGO_1_DELEGADO_DE_POLCIA_FEDERAL.pdf (fileId
--     1esMINWul7kGQsxkeXE50W-83ZpEBVVC9) - full 120-item CEBRASPE Certo/Errado
--     objective test, cover states "CARGO 1_DELEGADO DE POLÍCIA FEDERAL".
--   - Gabarito: GAB_DEFINITIVO_MATRIZ_577_PF_001_00.pdf (fileId
--     1EGBBNJzr0C3zBcuLK_BwVQqChwp7izjc) - explicitly labeled
--     "CARGO: DELEGADO DE POLÍCIA FEDERAL", Matriz_577_PF_001_00. This is the
--     matriz actually used: the other two matrizes read for comparison,
--     Matriz_577_PF_002_00 (fileId 1Q-1-D7711ji9JYtGanYX2S8Ir8FkUdSj) and
--     Matriz_577_PF_003_00 (fileId 1NPqhTeEj6HOw3867iU4kezMup5r19iOc), are
--     explicitly labeled "CARGO: AGENTE DE POLÍCIA FEDERAL" and
--     "CARGO: ESCRIVÃO DE POLÍCIA FEDERAL" respectively and were NOT used.
--     Matriz 002 (Agente) is byte-for-byte identical in its C/E/X sequence to
--     what 20260926050000/20260927080000 already imported for Agente 2021,
--     confirming the cargo labels on these gabarito PDFs are reliable and
--     that Matriz 001 (Delegado) is the correct source for this migration.
--
-- Root schema fix (mirrors the precedent set by
-- 20260927080000_fix_pf_prf_2021_collision.sql): the unique constraint
-- currently on official_exam_questions is
-- official_exam_questions_contest_year_item_key = (contest_name,exam_year,
-- item_number), set by 20260927000500_widen_exam_question_unique_key.sql.
-- That is not enough to distinguish this import: "Delegado de Polícia
-- Federal" and "Agente de Polícia Federal" share contest_name='Polícia
-- Federal' and exam_year=2021, and both have item_number 1-120, so without
-- career_name in the key this insert would silently collide with (or
-- overwrite) the existing Agente rows exactly like the PRF/DEPEN collision
-- previously did. This migration widens the constraint to include
-- career_name BEFORE inserting, and the insert's own ON CONFLICT target
-- matches the new, fully-distinguishing key.
alter table public.official_exam_questions
  drop constraint if exists official_exam_questions_contest_year_item_key;
alter table public.official_exam_questions
  drop constraint if exists official_exam_questions_contest_career_year_item_key;
alter table public.official_exam_questions
  add constraint official_exam_questions_contest_career_year_item_key
  unique (contest_name,career_name,exam_year,item_number);

-- Content sources for this specific cargo's booklet and gabarito matriz.
insert into public.content_sources (source_type,title,issuer,url,status,notes) values
('outro','Prova objetiva PF - Delegado - 2021','Polícia Federal / CEBRASPE','https://www.gov.br/pf/pt-br/acesso-a-informacao/servidores/concursos/provas-e-gabaritos-de-concursos-anteriores/concurso-carreira-policial-2021/delegado-de-policia-federal/prova_cargo_1_delegado_de_polcia_federal.pdf/view','vigente','Caderno oficial usado para extração auditável de itens (Google Drive fileId 1esMINWul7kGQsxkeXE50W-83ZpEBVVC9, texto lido verbatim nesta sessão).'),
('outro','Gabarito definitivo PF - Delegado - 2021','Polícia Federal / CEBRASPE','https://www.gov.br/pf/pt-br/acesso-a-informacao/servidores/concursos/provas-e-gabaritos-de-concursos-anteriores/concurso-carreira-policial-2021/delegado-de-policia-federal/gab_definitivo_dpf.pdf/view','vigente','Gabarito oficial definitivo Matriz_577_PF_001_00, explicitamente rotulado CARGO: DELEGADO DE POLICIA FEDERAL (Google Drive fileId 1EGBBNJzr0C3zBcuLK_BwVQqChwp7izjc); X identifica item anulado.')
on conflict (url) do update set checked_at=now(),status=excluded.status,notes=excluded.notes;

-- New syllabus edition for this career (distinct from the existing Agente
-- 2021 edition row).
insert into public.syllabus_editions (contest_name,role_name,contest_year)
select 'Polícia Federal','Delegado de Polícia Federal',2021
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Delegado de Polícia Federal' and contest_year=2021
);

-- Discipline breakdown derived directly from reading the prova's own item
-- text (command blocks and subject matter), not guessed: Direito
-- Administrativo (1-15), Direito Constitucional (16-30), Direito Civil
-- (31-33, 37-39), Direito Processual Civil (34-36), Direito Internacional
-- (40-46), Legislação Penal Especial (47-51, 75-85), Direito Penal
-- (52-74), Direito Processual Penal (86-102), Criminologia (103-105),
-- Direito Previdenciário (106-113), Direito Financeiro (114-115), Direito
-- Tributário (116-120).
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Delegado de Polícia Federal' and contest_year=2021
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Direito Administrativo','Improbidade administrativa, responsabilidade civil do Estado, controle da administração pública, delegação de competência e regime jurídico dos servidores públicos civis federais (Lei nº 8.429/1992, Lei nº 9.784/1999, Lei nº 8.112/1990).'),
  ('Direito Constitucional','Sentidos e concepções de constituição, direitos e deveres fundamentais, Poder Judiciário, segurança pública, atribuições constitucionais da Polícia Federal e controle de constitucionalidade.'),
  ('Direito Civil','Domicílio, responsabilidade civil e sociedades empresárias (sociedade limitada e sociedade em comum).'),
  ('Direito Processual Civil','Jurisdição, competência e poder geral de cautela no processo civil.'),
  ('Direito Internacional','Extradição e a Lei nº 13.445/2017 (Lei de Migração); Convenção das Nações Unidas contra o Crime Organizado Transnacional (Convenção de Palermo) e seu Protocolo Adicional relativo ao tráfico de pessoas.'),
  ('Legislação Penal Especial','Crimes previstos em legislação especial, incluindo Lei de Abuso de Autoridade, Lei nº 9.613/1998 (lavagem de dinheiro), Lei nº 7.492/1986 (crimes contra o Sistema Financeiro Nacional) e Lei nº 8.137/1990 (crimes contra a ordem tributária, econômica e relações de consumo).'),
  ('Direito Penal','Parte geral e parte especial do Código Penal: teoria geral do delito, teoria da pena, crimes contra a administração pública, crimes contra a fé pública.'),
  ('Direito Processual Penal','Prisão em flagrante e prisão preventiva, competência criminal, prova criminal, busca domiciliar, colaboração premiada e ação controlada.'),
  ('Criminologia','Prevenção primária, objetos da criminologia e controle social formal.'),
  ('Direito Previdenciário','Financiamento da seguridade social, segurado facultativo, contagem recíproca de tempo de contribuição e crimes previdenciários.'),
  ('Direito Financeiro','Emendas parlamentares impositivas, transferência especial constitucional e vinculação de receitas próprias dos estados.'),
  ('Direito Tributário','Princípios da anterioridade tributária, legislação tributária no CTN, imunidade tributária e suspensão da exigibilidade do crédito tributário.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

